import{_ as a,o as s,c as n,a5 as e}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"SHA1 是什么？Android、iOS 与鸿蒙签名发证有何不同","description":"SHA1 是证书指纹而非 APK 内容 hash；Android 自签名，iOS 与鸿蒙由平台发证，验签原理相同、身份门禁不同。","frontmatter":{"title":"SHA1 是什么？Android、iOS 与鸿蒙签名发证有何不同","date":"2026-05-19T00:00:00.000Z","tags":["uni-app","Android","iOS","鸿蒙","HarmonyOS","SHA1","签名"],"categories":["移动开发"],"description":"SHA1 是证书指纹而非 APK 内容 hash；Android 自签名，iOS 与鸿蒙由平台发证，验签原理相同、身份门禁不同。"},"headers":[],"relativePath":"posts/移动开发/uni-app/SHA1 是什么？Android、iOS 与鸿蒙签名发证有何不同.md","filePath":"posts/移动开发/uni-app/SHA1 是什么？Android、iOS 与鸿蒙签名发证有何不同.md","lastUpdated":1790163617000}'),o={name:"posts/移动开发/uni-app/SHA1 是什么？Android、iOS 与鸿蒙签名发证有何不同.md"};function d(r,t,p,i,l,h){return s(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="sha1-是什么-android、ios-与鸿蒙有何不同" tabindex="-1">SHA1 是什么？Android、iOS 与鸿蒙有何不同 <a class="header-anchor" href="#sha1-是什么-android、ios-与鸿蒙有何不同" aria-label="Permalink to &quot;SHA1 是什么？Android、iOS 与鸿蒙有何不同&quot;">​</a></h1><p>分两块说：<strong>SHA1 是什么</strong>，以及 <strong>为什么鸿蒙 / iOS 和 Android 不一样</strong>。</p><p>本文是 uni-app 离线打包系列补充。完整三平台流程见 <a href="/blog/posts/移动开发/uni-app/移动端打包签名与 DCloud 离线打包教程">移动端打包签名与 DCloud 离线打包教程</a>。相关阅读：<a href="/blog/posts/移动开发/uni-app/Android uni-app 生产包需要什么？签名 SHA1、keystore 与构建流程">生产包需要什么</a>、<a href="/blog/posts/移动开发/uni-app/Android keystore 密码与 APK 签名：打包时发生什么、安装时验什么">keystore 密码与 APK 验签</a>。</p><h2 id="sha1-是什么" tabindex="-1">SHA1 是什么？ <a class="header-anchor" href="#sha1-是什么" aria-label="Permalink to &quot;SHA1 是什么？&quot;">​</a></h2><p>前面说的 <strong>hash</strong> 是算法统称；<strong>SHA1</strong> 是其中一种具体算法（还有 SHA256 等）。</p><p>在 Android 签名语境里，SHA1 常指 <strong>证书的指纹</strong>，不是 APK 内容的 hash：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>证书（公钥 + 身份信息）</span></span>
<span class="line"><span>    ↓ 对证书本身做 SHA1 运算</span></span>
<span class="line"><span>SHA1 指纹：AA:BB:CC:DD:...（40 位十六进制）</span></span></code></pre></div><p>作用：<strong>给证书起个短编号</strong>，方便登记、对比。</p><table tabindex="0"><thead><tr><th></th><th>验签用的 hash</th><th>SHA1 指纹</th></tr></thead><tbody><tr><td><strong>算什么</strong></td><td>APK 文件内容</td><td>证书本身</td></tr><tr><td><strong>什么时候用</strong></td><td>每次安装验签</td><td>填 DCloud / 微信等后台</td></tr><tr><td><strong>会变吗</strong></td><td>改 APK 就变</td><td>同一张证永远一样</td></tr></tbody></table><p>DCloud 后台让你填 SHA1，意思是：<strong>「我登记的是这张签名证，以后只有这张证签的包我才认 AppKey。」</strong></p><h2 id="android-vs-ios-鸿蒙-谁发证" tabindex="-1">Android vs iOS / 鸿蒙：谁发证？ <a class="header-anchor" href="#android-vs-ios-鸿蒙-谁发证" aria-label="Permalink to &quot;Android vs iOS / 鸿蒙：谁发证？&quot;">​</a></h2><h3 id="android-自己签-自签名" tabindex="-1">Android：自己签（自签名） <a class="header-anchor" href="#android-自己签-自签名" aria-label="Permalink to &quot;Android：自己签（自签名）&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你自己生成 keystore</span></span>
<span class="line"><span>    → 自己给自己发证书（自签名）</span></span>
<span class="line"><span>    → 用私钥签 APK</span></span>
<span class="line"><span>    → 系统只验「签名对不对、更新是不是同一张证」</span></span>
<span class="line"><span>    → 不问你证书谁发的</span></span></code></pre></div><p>Google <strong>不给你发</strong> App 签名证书。你是自己的 CA。上架 Google Play 时可选 <strong>Play 代管签名</strong>，但本质仍是「开发者身份 = 某张证」。</p><h3 id="ios-apple-发证" tabindex="-1">iOS：Apple 发证 <a class="header-anchor" href="#ios-apple-发证" aria-label="Permalink to &quot;iOS：Apple 发证&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>加入 Apple 开发者计划（付费）</span></span>
<span class="line"><span>    → 在 Apple 后台申请 Development / Distribution 证书</span></span>
<span class="line"><span>    → Apple 当 CA，验证你是合法开发者后才发证</span></span>
<span class="line"><span>    → 还要 Provisioning Profile（绑定 Bundle ID + 证书 + 设备/商店）</span></span>
<span class="line"><span>    → 没有 Apple 发的证，真机装不上、上不了 App Store</span></span></code></pre></div><p><strong>Apple 控制整个链条</strong>：谁能开发、谁能装、谁能上架。</p><h3 id="鸿蒙-华为-appgallery-发证" tabindex="-1">鸿蒙：华为 / AppGallery 发证 <a class="header-anchor" href="#鸿蒙-华为-appgallery-发证" aria-label="Permalink to &quot;鸿蒙：华为 / AppGallery 发证&quot;">​</a></h3><p>和你们项目一样，证书在 <code>.secrets/harmonyos/</code>：</p><table tabindex="0"><thead><tr><th>文件</th><th>作用</th></tr></thead><tbody><tr><td><code>.cer</code></td><td>华为开发者平台发的数字证书</td></tr><tr><td><code>.p7b</code></td><td>Profile（类似 iOS 描述文件，绑定包名 / 权限）</td></tr><tr><td><code>.p12</code></td><td>私钥 + 证书打包（签名时用）</td></tr></tbody></table><p>流程和 iOS 很像：<strong>在华为开发者后台申请 → 平台发证 → 用这套签鸿蒙包</strong>。不是像 Android 那样自己 <code>keytool</code> 随便生成。</p><h2 id="核心区别一张表" tabindex="-1">核心区别一张表 <a class="header-anchor" href="#核心区别一张表" aria-label="Permalink to &quot;核心区别一张表&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Android</th><th>iOS</th><th>鸿蒙</th></tr></thead><tbody><tr><td><strong>谁发证</strong></td><td>自己（自签名）</td><td>Apple</td><td>华为</td></tr><tr><td><strong>门槛</strong></td><td>低，本地就能生成</td><td>开发者账号 + 审核</td><td>开发者账号 + 申请</td></tr><tr><td><strong>私钥在哪</strong></td><td>你的 <code>.keystore</code></td><td>Mac 钥匙串 / <code>.p12</code></td><td><code>.p12</code></td></tr><tr><td><strong>平台管控</strong></td><td>弱（侧载即可）</td><td>强</td><td>强</td></tr><tr><td><strong>DCloud 登记</strong></td><td>包名 + SHA1 + AppKey</td><td>Bundle ID + AppKey</td><td>包名 + 平台证书</td></tr></tbody></table><h2 id="为什么-ios-鸿蒙要平台发证" tabindex="-1">为什么 iOS / 鸿蒙要平台发证？ <a class="header-anchor" href="#为什么-ios-鸿蒙要平台发证" aria-label="Permalink to &quot;为什么 iOS / 鸿蒙要平台发证？&quot;">​</a></h2><p>Android 开放：<strong>有 APK + 允许未知来源就能装</strong>。<br> iOS / 鸿蒙封闭：<strong>只有平台认可的开发者 + 平台发的证，才能装、才能上架</strong>。</p><p>平台发证 = 平台先验证你是谁，再给你签名资格，比 Android 自签名多一层 <strong>身份门禁</strong>。</p><h2 id="和你们项目的关系" tabindex="-1">和你们项目的关系 <a class="header-anchor" href="#和你们项目的关系" aria-label="Permalink to &quot;和你们项目的关系&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Android  → .secrets/android/keystore/*.keystore（自管）</span></span>
<span class="line"><span>iOS      → Apple 开发者账号 + Xcode 签名（不在 Git 里）</span></span>
<span class="line"><span>鸿蒙     → .secrets/harmonyos/huayuan|sanli/（.cer/.p7b/.p12，华为发的）</span></span></code></pre></div><p><strong>验签原理三家一样</strong>（私钥签、公钥验），差别在 <strong>谁有权拿到那张证、能不能随便自签</strong>。</p><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p><strong>SHA1 是证书的身份证号</strong>；Android 自己发证，iOS / 鸿蒙 <strong>平台发证</strong>，管控更严。</p><hr><p><strong>系列导航</strong></p><ul><li><a href="/blog/posts/移动开发/uni-app/移动端打包签名与 DCloud 离线打包教程">移动端打包签名与 DCloud 离线打包教程（总览）</a></li><li><a href="/blog/posts/移动开发/uni-app/DCloud AppKey 是什么？离线打包三要素必须一致">DCloud AppKey 是什么？</a></li><li><a href="/blog/posts/移动开发/uni-app/Android uni-app 生产包需要什么？签名 SHA1、keystore 与构建流程">Android uni-app 生产包需要什么？</a></li><li><a href="/blog/posts/移动开发/uni-app/Android keystore 密码与 APK 签名：打包时发生什么、安装时验什么">Android keystore 密码与 APK 签名</a></li></ul>`,34)])])}const A=a(o,[["render",d]]);export{g as __pageData,A as default};
